#[derive(Debug, Clone, PartialEq)]
pub enum CallState {
    Idle,
    /// A room registered over REST, but without media: the signaling is missing.
    RoomCreated { channel_id: String, call_id: String },
}

pub struct CallSystem {
    creds: Credentials,
    channel_id: String,
    state: CallState,
}

impl CallSystem {
    pub fn new(creds: Credentials, channel_id: String) -> Self {
        CallSystem {
            creds,
            channel_id,
            state: CallState::Idle,
        }
    }

    pub fn state(&self) -> &CallState {
        &self.state
    }

    /// Calls `rooms.join` and reports the shape of the response, then leaves
    /// again straight away with `rooms.leave`.
    ///
    /// It serves to answer a single question: **is an `xoxc` token accepted?** It
    /// establishes no media.
    ///
    /// Careful: `rooms.join` creates a real huddle, visible in the channel.
    /// Leaving immediately reduces it to a fraction of a second's appearance, but
    /// does not make it invisible.
    pub async fn probe(
        &mut self,
        show_secrets: bool,
        connect: bool,
        audio: bool,
        hold_secs: u64,
        dump_sdp: Option<std::path::PathBuf>,
        unmuted: bool,
        interactive: bool,
        devices: &crate::calls::session::Devices,
    ) -> Result<()> {
        let api = ApiClient::new(self.creds.clone());

        println!("→ rooms.join channel_id={}", self.channel_id);
        // `regions` empty: the official client sends it like that when it has
        // not yet resolved the nearest Chime region.
        let resp = api.rooms_join(&self.channel_id, "", false).await?;

        let call = resp.get("call").cloned().unwrap_or(serde_json::Value::Null);
        let call_id = call
            .get("call_id")
            .and_then(|v| v.as_str())
            .unwrap_or_default()
            .to_string();

        // The Chime branch is the one we care about; the other is the old
        // ScreenHero and is to be recognised, not implemented.
        let free_willy = call.get("free_willy");
        let attendee_id = free_willy
            .and_then(|f| f.get("attendee"))
            .and_then(|a| {
                a.get("AttendeeId")
                    .or_else(|| a.get("attendeeId"))
                    .or_else(|| a.get("attendee_id"))
            })
            .and_then(|v| v.as_str())
            .unwrap_or_default()
            .to_string();

        println!();
        println!("{}", serde_json::to_string_pretty(&redact(&resp, show_secrets))?);
        println!();

        match free_willy {
            Some(fw) => {
                println!("✓ Chime backend (free_willy) present");
                let signaling = fw
                    .get("meeting")
                    .and_then(|m| m.get("MediaPlacement").or_else(|| m.get("mediaPlacement")))
                    .and_then(|mp| {
                        mp.get("SignalingUrl")
                            .or_else(|| mp.get("signalingUrl"))
                            .or_else(|| mp.get("signaling_url"))
                    })
                    .and_then(|v| v.as_str());
                match signaling {
                    Some(url) => println!("  signaling: {url}"),
                    None => println!("  ⚠ no SignalingUrl: unexpected shape"),
                }
                println!("  attendee:  {}", if attendee_id.is_empty() { "(absent)" } else { &attendee_id });
            }
            None => {
                println!("⚠ no `free_willy`: response on the legacy ScreenHero branch.");
                println!("  This backend is not implemented.");
            }
        }

        self.state = CallState::RoomCreated {
            channel_id: self.channel_id.clone(),
            call_id: call_id.clone(),
        };

        if connect || audio {
            self.connect_signaling(free_willy, audio, hold_secs, dump_sdp.as_deref(), &call_id, unmuted, interactive, devices)
                .await?;
        } else {
            // `rooms.join` allocates a *prewarmed* room: it enrols nobody until
            // you connect to the SFU. A room nobody enters is closed by Slack in
            // about two minutes (measured).
            println!();
            println!("Note: a `huddle_thread` message appears in the channel.");
            println!("The room closes on its own in ~2 min if nobody connects.");
            println!("With --connect the signaling really opens (you become a participant).");
        }

        self.state = CallState::Idle;
        Ok(())
    }

    /// Opens the Chime signaling, sends JOIN and reports the JOIN_ACK.
    ///
    /// This is the point at which you become a real participant in the huddle:
    /// from here on the colleagues in the channel see it as active.
    async fn connect_signaling(
        &self,
        free_willy: Option<&serde_json::Value>,
        with_audio: bool,
        hold_secs: u64,
        dump_sdp: Option<&std::path::Path>,
        call_id: &str,
        unmuted: bool,
        interactive: bool,
        devices: &crate::calls::session::Devices,
    ) -> Result<()> {
        use crate::calls::signaling::{frame_type, SignalingClient};

        let fw = free_willy.context("no `free_willy`: nothing to connect")?;

        let pick = |obj: Option<&serde_json::Value>, keys: &[&str]| -> Option<String> {
            let o = obj?;
            keys.iter()
                .find_map(|k| o.get(k))
                .and_then(|v| v.as_str())
                .map(str::to_string)
        };

        let placement = fw
            .get("meeting")
            .and_then(|m| m.get("MediaPlacement").or_else(|| m.get("mediaPlacement")));
        let signaling_url = pick(placement, &["SignalingUrl", "signalingUrl"])
            .context("SignalingUrl missing from the response")?;
        let join_token = pick(fw.get("attendee"), &["JoinToken", "joinToken"])
            .context("JoinToken missing from the response")?;

        println!();
        println!("→ signaling {signaling_url}");

        let close_on_error = std::env::var("SLAQ_NO_CLOSE_ON_ERROR").is_err();
        let mut sig =
            SignalingClient::connect_with(&signaling_url, &join_token, close_on_error).await?;
        println!("✓ WebSocket open");

        let (ack, extra) = sig.join().await?;
        println!("✓ JOIN_ACK ricevuto");
        if let Some(turn) = &ack.turn_credentials {
            println!("  TURN uri     : {:?}", turn.uris);
            println!("  TURN username: {:?}", turn.username);
            println!("  TTL          : {:?}", turn.ttl);
        }
        if let Some(limit) = ack.video_subscription_limit {
            println!("  video limit  : {limit}");
        }
        for f in &extra {
            let name = match f.r#type {
                frame_type::INDEX => "INDEX",
                other => return Ok(println!("  frame type {other} before the ack")),
            };
            println!("  {name} received before the ack");
        }

        let mut media: Option<crate::calls::session::MediaSession> = None;

        if with_audio {
            let audio_host = pick(placement, &["AudioHostUrl", "audioHostUrl"])
                .context("AudioHostUrl missing from the response")?;
            let attendee_id = pick(fw.get("attendee"), &["AttendeeId", "attendeeId"])
                .context("AttendeeId missing from the response")?;

            println!();
            println!(
                "→ negoziazione media (audio, {})",
                if unmuted { "microphone OPEN" } else { "declared muted" }
            );
            // Note: `muted` is only what is declared to the SFU. The
            // microphone is opened and transmits anyway, which is a
            // contradiction: it is told "I am muted" while being sent 50
            // packets a second. It is there to find out whether that is why
            // it cannot hear us.
            let session = crate::calls::session::MediaSession::negotiate(
                &mut sig,
                &ack,
                &attendee_id,
                &audio_host,
                !unmuted,
                dump_sdp,
                devices,
                // The probe is diagnostic: a shared screen would have nowhere
                // to be shown.
                None,
            )
            .await?;
            println!("✓ SUBSCRIBE_ACK, SDP exchanged");

            match session
                .wait_connected(std::time::Duration::from_secs(20))
                .await
            {
                Ok(()) => println!("✓ PeerConnection connected to the SFU"),
                Err(e) => println!("⚠ {e}"),
            }
            media = Some(session);
        }

        if hold_secs > 0 || interactive {
            if interactive {
                println!("  in a call");
            } else {
                println!("  staying connected {hold_secs}s...");
            }
            // The signaling has to be served while holding the session too:
            // the server sends a ping every 10 s and closes if it gets no answer.
            let deadline =
                tokio::time::Instant::now() + std::time::Duration::from_secs(hold_secs);
            let mut ping_timer = tokio::time::interval(
                std::time::Duration::from_millis(
                    crate::calls::signaling::PING_INTERVAL_MS,
                ),
            );
            // The first tick fires immediately: it is consumed so as not to
            // send a redundant ping right after the JOIN.
            ping_timer.tick().await;
            let mut ping_id: u32 = 0;
            let mut signaling_down = false;
            let mut watch = tokio::time::interval(std::time::Duration::from_secs(1));
            // The official client sends `CLIENT_METRIC` every exact second,
            // without a break (captured on 2026-09-30). Between the `SUBSCRIBE`
            // and the first ping we were silent for ten seconds, and the server
            // closed at three: the first thing to check is whether some traffic
            // is all it wants.
            let mut metrics = tokio::time::interval(std::time::Duration::from_secs(1));
            metrics.tick().await;
            let started = tokio::time::Instant::now();

            // Interactive mode: you stay in until you hang up, and mute is
            // driven from the keyboard.
            let mut key_rx = if interactive {
                crossterm::terminal::enable_raw_mode().ok();
                println!();
                println!("  [space] mute   [q] hang up");
                println!();
                Some(keys())
            } else {
                None
            };

            loop {
                tokio::select! {
                    // In interactive mode you only leave by hanging up: the deadline
                    // must not interrupt a conversation.
                    _ = tokio::time::sleep_until(deadline), if !interactive => break,
                    _ = watch.tick() => {
                        // The official client sends metrics continuously once the
                        // media is up: we try whether receiving them is enough for the
                        // server not to close.
                        if !signaling_down && media.is_some() {
                            if let Err(e) = sig
                                .send_client_metrics(Default::default())
                                .await
                            {
                                println!("  ⚠ sending metrics failed: {e:#}");
                                signaling_down = true;
                            }
                        }
                        if let Some(m) = &media {
                            // How many packets we are really sending: without this
                            // there is no telling "track attached" from "track that
                            // transmits", and that is the difference that matters to
                            // the SFU.
                            let mut sent = 0u64;
                            let mut recv = 0u64;
                            // How much leaves and how much enters the *transport*: the
                            // packets counted above are the ones handed to the sender,
                            // these are the ones that really left the chosen candidate
                            // pair.
                            let (mut tx, mut rx, mut pair) = (0u64, 0u64, String::new());
                            for (_, st) in m.pc.get_stats().await.reports {
                                match &st {
                                    webrtc::stats::StatsReportType::OutboundRTP(o) => {
                                        sent += o.packets_sent
                                    }
                                    webrtc::stats::StatsReportType::InboundRTP(i) => {
                                        recv += i.packets_received
                                    }
                                    webrtc::stats::StatsReportType::CandidatePair(c)
                                        if c.nominated =>
                                    {
                                        tx += c.bytes_sent;
                                        rx += c.bytes_received;
                                        pair = format!("{:?}", c.state);
                                    }
                                    _ => {}
                                }
                            }
                            let _ = &pair;
                            let _ = (tx, rx);
                            if interactive {
                                // In raw mode the terminal does not return the
                                // carriage by itself: without `\r` every line starts
                                // where the previous one ended. We always rewrite the
                                // same line.
                                use std::io::Write as _;
                                let muted = m.is_muted().await;
                                print!(
                                    "\r  in chiamata · {} · {}s · inviati {} ricevuti {}        ",
                                    if muted { "MUTED" } else { "microphone open" },
                                    started.elapsed().as_secs(),
                                    sent,
                                    recv,
                                );
                                std::io::stdout().flush().ok();
                            } else {
                                println!(
                                    "  [{:>2}s] media={:<12} sig={:<4} rtp out={} in={}",
                                    started.elapsed().as_secs(),
                                    m.pc.connection_state().to_string(),
                                    if signaling_down { "giù" } else { "su" },
                                    sent,
                                    recv,
                                );
                            }
                        }
                    }
                    Some(c) = async {
                        match key_rx.as_mut() {
                            Some(rx) => rx.recv().await,
                            // With no keyboard this branch must never be chosen: an
                            // immediate `None` would make it spin and burn CPU.
                            None => std::future::pending().await,
                        }
                    } => {
                        match c {
                            ' ' => if let Some(m) = &media {
                                let muted = m.toggle_mute().await;
                                let _ = muted;
                            },
                            'q' => {
                                println!("\r  hanging up…                                        ");
                                break;
                            }
                            _ => {}
                        }
                    }
                    _ = metrics.tick(), if !signaling_down => {
                        // Plausible values, not yet taken from the real
                        // statistics: first we need to know whether the right *shape*
                        // is enough for the server. The empty frame was not.
                        let sample = crate::calls::signaling::MetricSample {
                            rtt_ms: 25.0,
                            mic_pps: 50.0,
                            mic_bitrate: 16_000.0,
                            spk_pps: 50.0,
                            spk_bitrate: 16_000.0,
                        };
                        if let Err(e) = sig
                            .send_client_metrics(
                                crate::calls::signaling::client_metrics(sample),
                            )
                            .await
                        {
                            println!("  ⚠ metrics failed: {e:#}");
                            signaling_down = true;
                        }
                    }
                    _ = ping_timer.tick(), if !signaling_down => {
                        ping_id += 1;
                        if let Err(e) = sig.send_ping(ping_id).await {
                            println!("  ⚠ ping failed: {e:#}");
                            signaling_down = true;
                        }
                    }
                    frame = sig.recv_frame(), if !signaling_down => match frame {
                        Ok(Some(f)) => {
                            // *Everything* that arrives is printed: before, only the
                            // error field was looked at, and what the server says before
                            // closing was escaping us.
                            if !interactive {
                                println!(
                                    "  <-- {} ({:.1}s)",
                                    frame_name(f.r#type),
                                    started.elapsed().as_secs_f32(),
                                );
                            }
                            // The per-participant audio levels say whether the SFU
                            // is really hearing us: that is the question that matters, and
                            // until now we were throwing it away.
                            if let Some(md) = &f.audio_metadata {
                                for a in &md.attendee_states {
                                    if interactive {
                                        continue;
                                    }
                                    println!(
                                        "      stream={} volume={:?} muted={:?} signal={:?}",
                                        a.audio_stream_id.unwrap_or(0),
                                        a.volume,
                                        a.muted,
                                        a.signal_strength,
                                    );
                                }
                            }
                            if let Some(info) = &f.audio_stream_id_info {
                                for st in &info.streams {
                                    if interactive {
                                        continue;
                                    }
                                    println!(
                                        "      mappa: stream={} attendee={:?}",
                                        st.audio_stream_id.unwrap_or(0),
                                        st.attendee_id,
                                    );
                                }
                            }
                            if let Some(err) = &f.error {
                                println!("  ⚠ error from the server: {err:?}");
                            }
                        }
                        Ok(None) => {
                            println!("  ⚠ signaling closed by the server");
                            signaling_down = true;
                        }
                        Err(e) => {
                            // We do not leave: we need to know whether the media holds.
                            println!("  ⚠ signaling caduto: {e:#}");
                            signaling_down = true;
                        }
                    }
                }
            }
        }

        if interactive {
            crossterm::terminal::disable_raw_mode().ok();
        }

        if let Some(m) = media {
            m.close().await.ok();
        }

        println!();
        println!("→ LEAVE");
        // The `leave` on the signaling is not enough: when the socket has
        // already dropped — which is precisely the case to diagnose — it never
        // goes out, and the room stays open. On a channel with colleagues it
        // would sit there in front of everyone.
        if let Err(e) = sig.leave().await {
            println!("  ⚠ LEAVE on signaling failed: {e:#}");
        }
        let api = ApiClient::new(self.creds.clone());
        let _leave_attendee = pick(fw.get("attendee"), &["AttendeeId", "attendeeId"])
            .unwrap_or_default();
        // No `rooms.leave`: the official client does not use it. The room
        // closes when the Chime attendee leaves, that is, with the `LEAVE` above.
        let _ = (&api, call_id);

        Ok(())
    }
}

/// Reads the keys from the terminal and sends them on the channel.
///
/// It runs on a system thread: crossterm blocks, and blocking a tokio worker
/// would stop the audio as well.
fn keys() -> tokio::sync::mpsc::UnboundedReceiver<char> {
    let (tx, rx) = tokio::sync::mpsc::unbounded_channel();
    std::thread::spawn(move || {
        use crossterm::event::{self, Event, KeyCode};
        loop {
            match event::read() {
                Ok(Event::Key(k)) => {
                    let c = match k.code {
                        KeyCode::Char(' ') => ' ',
                        KeyCode::Char(c) => c,
                        KeyCode::Esc => 'q',
                        _ => continue,
                    };
                    if tx.send(c).is_err() {
                        return;
                    }
                }
                Ok(_) => {}
                Err(_) => return,
            }
        }
    });
    rx
}

/// Readable name of a signaling frame type.
fn frame_name(t: i32) -> String {
    use crate::calls::signaling::frame_type as ft;
    match t {
        ft::JOIN => "JOIN".into(),
        ft::JOIN_ACK => "JOIN_ACK".into(),
        ft::SUBSCRIBE => "SUBSCRIBE".into(),
        ft::SUBSCRIBE_ACK => "SUBSCRIBE_ACK".into(),
        ft::INDEX => "INDEX".into(),
        ft::LEAVE => "LEAVE".into(),
        other => format!("tipo {other}"),
    }
}

/// Leaves the room over REST, which does not depend on the signaling
/// socket.
///
/// The errors are benign by definition: if the room is gone, having left is
/// exactly the intended result.
async fn leave_room(
    api: &crate::api::Client,
    channel: &str,
    call_id: &str,
    attendee_id: &str,
) {
    if call_id.is_empty() {
        return;
    }
    match api.rooms_leave(channel, call_id, attendee_id, "left").await {
        Ok(v) if v.get("ok").and_then(|o| o.as_bool()) == Some(true) => {
            println!("✓ left the room");
        }
        Ok(v) => println!(
            "  room: {}",
            v.get("error").and_then(|e| e.as_str()).unwrap_or("risposta inattesa")
        ),
        Err(e) => println!("  ⚠ rooms.leave failed: {e:#}"),
    }
}

/// Hides the sensitive values before printing them.
///
/// The response contains a `joinToken` and credentials: they end up in the
/// terminal scrollback and in any screenshot. The *shape* is visible all the
/// same, and that is what is needed.
fn redact(v: &serde_json::Value, show_secrets: bool) -> serde_json::Value {
    use serde_json::Value;

    if show_secrets {
        return v.clone();
    }

    const SENSITIVE: &[&str] = &["token", "password", "secret", "credential", "auth"];

    match v {
        Value::Object(map) => Value::Object(
            map.iter()
                .map(|(k, val)| {
                    let lower = k.to_lowercase();
                    let hit = SENSITIVE.iter().any(|s| lower.contains(s));
                    if hit {
                        if let Value::String(s) = val {
                            return (k.clone(), Value::String(format!("<{} caratteri nascosti>", s.len())));
                        }
                    }
                    (k.clone(), redact(val, show_secrets))
                })
                .collect(),
        ),
        Value::Array(items) => Value::Array(items.iter().map(|i| redact(i, show_secrets)).collect()),
        other => other.clone(),
    }
}
